class Solution {
public:
    int videoStitching(vector<vector<int>>& clips, int time) {
        vector<int> max_reach(time + 1, 0);
        for (const auto& clip : clips) {
            if (clip[0] <= time) {
                max_reach[clip[0]] = max(max_reach[clip[0]], clip[1]);
            }
        }

        int jumps = 0, cur_end = 0, next_end = 0;
        for (int i = 0; i < time; ++i) {
            next_end = max(next_end, max_reach[i]);
            if (i == cur_end) {
                jumps++;
                cur_end = next_end;
                if (cur_end >= time) return jumps;
                if (cur_end <= i) return -1;
            }
        }
        return cur_end >= time ? jumps : -1;
    }
};

class Solution {
    public int videoStitching(int[][] clips, int time) {
        int[] maxReach = new int[time + 1];
        for (int[] clip : clips) {
            if (clip[0] <= time) {
                maxReach[clip[0]] = Math.max(maxReach[clip[0]], clip[1]);
            }
        }

        int jumps = 0, curEnd = 0, nextEnd = 0;
        for (int i = 0; i < time; ++i) {
            nextEnd = Math.max(nextEnd, maxReach[i]);
            if (i == curEnd) {
                jumps++;
                curEnd = nextEnd;
                if (curEnd >= time) return jumps;
                if (curEnd <= i) return -1;
            }
        }
        return curEnd >= time ? jumps : -1;
    }
}

var videoStitching = function(clips, time) {
    const maxReach = new Array(time + 1).fill(0);
    for (const [start, end] of clips) {
        if (start <= time) {
            maxReach[start] = Math.max(maxReach[start], end);
        }
    }

    let jumps = 0;
    let curEnd = 0;
    let nextEnd = 0;
    for (let i = 0; i < time; i++) {
        nextEnd = Math.max(nextEnd, maxReach[i]);
        if (i === curEnd) {
            jumps++;
            curEnd = nextEnd;
            if (curEnd >= time) return jumps;
            if (curEnd <= i) return -1;
        }
    }
    return curEnd >= time ? jumps : -1;
};
